import { canonicalPlatformHostTools, withPlatformHostToolAliases } from "../platform-host-tools.js";
import { createPlatformMcpCatalogSource, withPlatformMcpPolicyAliases, } from "../platform-mcp-tool-source.js";
import { createRemoteMCPToolSource, createToolsFromRemoteDefinitions, } from "../../tool/index.js";
import { markTrustedHostToolSet } from "../../tool/host-tool-provenance.js";
import { AGENT_ERROR } from "../../errors/index.js";
import { isErrorAcrossRealms } from "../../platform/compat/error-introspection.js";
import { createAgentServiceRemoteMcpConfig, defaultAgentServiceMcpServers, } from "../service/mcp-server-config.js";
import { createAgentServiceSandboxTools, } from "../../sandbox/index.js";
import { createLiveStudioMcpTools, } from "../project/live-studio-mcp-tools.js";
import { wrapHostedChildProjectSwitchTool, } from "./child-steering-tools.js";
import { buildDefaultHostedChildForkToolSet, } from "./child-requested-tools.js";
import { createMcpToolPolicyGate, wrapHostToolSetWithMcpPolicy } from "../mcp-tool-policy.js";
import { filterVeryfrontApiToolDefinitionsWithAccessProfile, resolveVeryfrontApiToolAccessProfileToolName, } from "./veryfront-api-tool-access.js";
import { createHostedMcpToolPolicySource, throwExplicitStudioMcpUnavailable, } from "./project-remote-tool-source.js";
/** Prepare default hosted child fork tool sources. */
export async function prepareDefaultHostedChildForkToolSources(input) {
    throwIfAborted(input.abortSignal);
    let closeStudioMcpTools;
    let studioMcpTools = {};
    let remoteMcpTools = {};
    const createLiveStudioTools = input.createLiveStudioTools ?? createLiveStudioMcpTools;
    const createRemoteToolSource = input.createRemoteToolSource ?? createRemoteMCPToolSource;
    const materializeRemoteTools = input.createToolsFromRemoteDefinitions ??
        createToolsFromRemoteDefinitions;
    try {
        const mcpServers = input.mcpServers ?? defaultAgentServiceMcpServers();
        for (const server of mcpServers) {
            if (server.kind === "veryfront-studio") {
                const remoteConfig = createAgentServiceRemoteMcpConfig({
                    server,
                    authToken: input.authToken,
                    apiMcpUrl: input.apiMcpUrl,
                    studioMcpUrl: input.studioMcpUrl,
                    clientProfile: input.clientProfile,
                    getProjectId: input.getProjectId,
                    conversationId: input.conversationId,
                });
                if (!remoteConfig) {
                    if (server.required !== false)
                        throwExplicitStudioMcpUnavailable(input);
                    continue;
                }
                const studioTools = await createLiveStudioTools({
                    authToken: input.authToken,
                    clientProfile: input.clientProfile,
                    getProjectId: input.getProjectId,
                    studioMcpUrl: input.studioMcpUrl,
                    ...(input.conversationId ? { conversationId: input.conversationId } : {}),
                    ...(input.createRemoteToolSource
                        ? { createRemoteToolSource: input.createRemoteToolSource }
                        : {}),
                });
                const policyTools = wrapHostToolSetWithMcpPolicy(studioTools.tools, withPlatformMcpPolicyAliases(server.toolPolicy), {
                    deniedDetail: (toolName) => `Tool "${toolName}" is not allowed for this MCP server`,
                });
                studioMcpTools = {
                    ...studioMcpTools,
                    ...canonicalPlatformHostTools(markTrustedHostToolSet(policyTools)),
                };
                closeStudioMcpTools = studioTools.close;
                continue;
            }
            const remoteConfig = createAgentServiceRemoteMcpConfig({
                server,
                authToken: input.authToken,
                apiMcpUrl: input.apiMcpUrl,
                getProjectId: input.getProjectId,
                defaultSourceId: "veryfront-mcp-fork",
            });
            if (!remoteConfig) {
                continue;
            }
            const rawSource = createRemoteToolSource(remoteConfig);
            const rawDefinitions = await rawSource.listTools();
            const accessFilteredDefinitions = server.kind === "veryfront-api"
                ? await filterVeryfrontApiToolDefinitionsWithAccessProfile({
                    source: rawSource,
                    toolDefinitions: rawDefinitions,
                    projectId: input.getProjectId() ?? null,
                    profileToolName: resolveVeryfrontApiToolAccessProfileToolName(rawDefinitions),
                })
                : rawDefinitions;
            const catalog = server.kind === "veryfront-api"
                ? createPlatformMcpCatalogSource(rawSource, accessFilteredDefinitions)
                : {
                    source: rawSource,
                    definitions: accessFilteredDefinitions.filter(({ name }) => !name.startsWith("veryfront__")),
                };
            const policy = server.kind === "veryfront-api"
                ? withPlatformMcpPolicyAliases(server.toolPolicy)
                : server.toolPolicy;
            const policySource = createHostedMcpToolPolicySource(catalog.source, policy);
            const definitions = createMcpToolPolicyGate(policy).filterDefinitions(catalog.definitions);
            remoteMcpTools = {
                ...remoteMcpTools,
                ...materializeRemoteTools(policySource, definitions),
            };
        }
    }
    catch (error) {
        if (input.abortSignal?.aborted || input.isAbortError?.(error)) {
            throw error;
        }
        input.logger?.error("Failed to initialize MCP tool sources for child fork", {
            mcpError: error,
        });
        return {
            ok: false,
            errorMessage: `MCP tool setup failed: ${error instanceof Error ? error.message : "Unknown error"}`,
        };
    }
    throwIfAborted(input.abortSignal);
    if (input.onConfirmedStudioProjectSwitch) {
        wrapHostedChildProjectSwitchTool({
            tools: studioMcpTools,
            toolName: "veryfront__studio_open_project",
            onConfirmedProjectSwitch: input.onConfirmedStudioProjectSwitch,
        });
    }
    throwIfAborted(input.abortSignal);
    return {
        ok: true,
        forkTools: buildDefaultHostedChildForkToolSet(remoteMcpTools, studioMcpTools, input.globalTools ?? {}),
        closeStudioMcpTools,
    };
}
/** Prepare default hosted child fork sandbox tool sources. */
export async function prepareDefaultHostedChildForkSandboxToolSources(input) {
    const { apiUrl, getAuthToken, createBashTool, createAgentServiceSandboxTools: createAgentServiceSandboxToolsOverride, globalTools, ...toolSourceInput } = input;
    const createSandboxTools = createAgentServiceSandboxToolsOverride ??
        createAgentServiceSandboxTools;
    const sandboxResult = await createSandboxTools({
        authToken: input.authToken,
        ...(getAuthToken ? { getAuthToken } : {}),
        apiUrl,
        getProjectId: input.getProjectId,
        createBashTool,
    });
    const mergedGlobalTools = withPlatformHostToolAliases(sandboxResult.tools, globalTools);
    try {
        const toolSources = await prepareDefaultHostedChildForkToolSources({
            ...toolSourceInput,
            globalTools: mergedGlobalTools,
        });
        if (!toolSources.ok) {
            try {
                await sandboxResult.closeSandbox();
            }
            catch (closeError) {
                input.logger?.error("Failed to close sandbox during child fork tool source cleanup", {
                    errorName: closeError instanceof Error ? closeError.name : typeof closeError,
                });
            }
            return toolSources;
        }
        return {
            ok: true,
            forkTools: toolSources.forkTools,
            closeRuntime: sandboxResult.closeSandbox,
            closeTooling: toolSources.closeStudioMcpTools,
        };
    }
    catch (error) {
        // Never let a close failure mask the original error that triggered cleanup.
        try {
            await sandboxResult.closeSandbox();
        }
        catch (closeError) {
            input.logger?.error("Failed to close sandbox during child fork tool source cleanup", {
                errorName: closeError instanceof Error ? closeError.name : typeof closeError,
            });
        }
        throw error;
    }
}
function throwIfAborted(abortSignal) {
    if (!abortSignal?.aborted) {
        return;
    }
    const reason = abortSignal.reason;
    if (isErrorAcrossRealms(reason)) {
        throw reason;
    }
    throw AGENT_ERROR.create({ detail: "Child fork aborted" });
}
